def transform(wb):
    ws = wb['Sheet1']
    found = None
    for row in range(4, ws.max_row + 1):
        if found is None:
            value = ws.cell(row=row, column=1).value
            if value is not None:
                text = str(value).strip().lower()
                if text.find('invoice no.') >= 0:
                    found = row
    if found is not None and found > 4:
        ws.delete_rows(4, found - 4)
